const helpers=this.helpers;
const KEY='<REDACTED_SUPABASE_JWT>';
const BASE='https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const H={apikey:KEY,Authorization:'Bearer '+KEY};
const needs=($('Find Missing URNs').first().json.needs)||[];
function norm(u){return String(u||'').trim().toLowerCase().replace(/\/+$/,'');}
function slugFromUrl(u){const m=norm(u).match(/\/company\/([^\/?#]+)/);return m?m[1]:null;}
function looksSlugDerived(name,slug){const n=String(name||'').trim();if(!n)return true;if(slug){const sw=slug.replace(/-/g,' ').toLowerCase().trim();if(n.toLowerCase()===slug.toLowerCase())return true;if(n.toLowerCase()===sw)return true;}if(!/\s/.test(n)&&n===n.toLowerCase()&&/[-_]/.test(n))return true;return false;}
function extractDomain(r){const bi=r.basic_info||{};const cand=r.website||r.domain||bi.website||bi.domain||(bi.websites&&bi.websites[0])||null;if(!cand)return null;try{const u=new URL(String(cand).match(/^https?:\/\//)?cand:('https://'+cand));return u.hostname.replace(/^www\./,'').toLowerCase();}catch(e){return String(cand).replace(/^https?:\/\//,'').replace(/^www\./,'').split('/')[0].toLowerCase()||null;}}
const updates=[];
for(const item of $input.all()){
  const r=item.json||{};const bi=r.basic_info||{};
  const urn=r.company_urn||bi.company_urn||null;
  if(!urn)continue;
  const ident=norm(r.input_identifier);
  const slug=bi.universal_name?norm(bi.universal_name):null;
  let comp=needs.find(c=>norm(c.linkedin_url)===ident);
  if(!comp&&slug)comp=needs.find(c=>slugFromUrl(c.linkedin_url)===slug);
  if(!comp&&ident)comp=needs.find(c=>norm(c.linkedin_url).indexOf(ident)!==-1||ident.indexOf(norm(c.linkedin_url))!==-1);
  if(!comp)continue;
  const urlSlug=slug||slugFromUrl(comp.linkedin_url);
  const actorName=(bi.name&&String(bi.name).trim())?String(bi.name).trim():null;
  const actorDomain=extractDomain(r);
  const finalName=(actorName&&looksSlugDerived(comp.name,urlSlug))?actorName:comp.name;
  const currentDomain=(comp.domain&&String(comp.domain).trim())?String(comp.domain).trim().toLowerCase().replace(/^www\./,''):null;
  const finalDomain=currentDomain||actorDomain||null;
  updates.push({match_url:comp.linkedin_url,name:finalName,linkedin_urn:String(urn),domain:finalDomain});
}
let n=0;
for(const u of updates){
  try{await helpers.httpRequest({method:'PATCH',url:BASE+'/competitors?linkedin_url=eq.'+encodeURIComponent(u.match_url),headers:Object.assign({},H,{'Content-Type':'application/json','Prefer':'return=minimal'}),body:{linkedin_urn:u.linkedin_urn,name:u.name,domain:u.domain},json:true});n++;}catch(e){}
}
return [{json:{resolved:n,attempted:updates.length}}];
